"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["98375"],{71853(e,t,n){n.d(t,{Ay:()=>r,RM:()=>a});var s=n(74848),o=n(28453);let a=[];function i(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"the-5-month-moving-average-grand-ambush-script-plays-out-as-expected",children:"The 5-Month Moving Average Grand Ambush Script Plays Out as Expected"})}),"\n",(0,s.jsxs)(t.blockquote,{children:["\n",(0,s.jsx)(t.p,{children:"2007/11/9 15:20:08"}),"\n"]}),"\n",(0,s.jsxs)("div",{style:{color:"#009900",fontWeight:"500",fontSize:"18px"},children:[(0,s.jsx)(t.p,{children:"There's nothing to say about today's market \u2014 it's just the live version of the 5-month moving average grand ambush script that this ID already published the past couple of days. But to be honest, the same script with different directors naturally produces different effects. Today's performance level was clearly not very satisfying, which is why this ID gave a verdict first thing this morning: \"These foolish bulls probably can't even copy things properly.\" As for whether they'll ultimately \"bid farewell to the 5-month moving average in a frenzied night,\" that answer will come soon enough."}),(0,s.jsx)(t.p,{children:"Of course, before that answer arrives, regardless of the outcome, there will be a throwback confirmation process to the neckline at 5462-5555 points. This is standard procedure. If it can get back above, it proves the bulls didn't botch this 5-month moving average ambush script; otherwise, the show needs a refund and we start over with the bears' monster performance."}),(0,s.jsx)(t.p,{children:"This bear-monster will definitely be hacked and chopped by this ID in the end, but if the bulls don't step up, if the script is botched, the first ones getting hacked and chopped will definitely be the bulls."}),(0,s.jsx)(t.p,{children:"This ID \u2014 a bear who wants to kill the bears \u2014 currently loves doing this most: when the bulls set up an ambush, this ID lies in ambush behind them; when the bulls charge, this ID cheers along; when the bulls run out of steam and the bears counterattack, this ID swoops in from behind for a continuous slaughter, turning bulls into barely-bulls."}),(0,s.jsx)(t.p,{children:"Some might say this is too shameless. This ID only knows that in the capital market, the most shameless behavior is losing money and getting trapped. As long as you're in the market, stay away from such behavior, and you'll naturally be a noble person, a person free from vulgar interests, and a person entitled to look down upon all who call you shameless."}),(0,s.jsx)(t.p,{children:"It's like warfare \u2014 Chiang Kai-shek was the most shameless man of all. With every advantage, he still got chased to an island to take saltwater baths. Is there anything in this world more shameless than that? No matter how many shameless people find ten thousand shameless excuses for him, it doesn't change the conclusion that he was the most shameless. In war, only results matter \u2014 don't give any reasons. If you lose, go grind the wall. Whining and complaining are useless."}),(0,s.jsx)(t.p,{children:"The market is even more merciless than war. Lose a war, and shameless literati will spin tales of this hero and that champion, fooling children. Lose in the market, and nobody will even collect your bones. Some people like warmth, like someone to speak softly and comfort their broken hearts \u2014 that's a disease. Such people have only one destiny in the market: death."}),(0,s.jsx)(t.p,{children:"PetroChina has a new 1-minute hub around 38, but this hub is too close to the one above, so it's highly likely they'll merge into a larger-level hub. Of course, the actual trend is determined by the market."}),(0,s.jsx)(t.p,{children:"Nothing to say about the broader market. After the 5-month moving average ambush, just watch the throwback momentum \u2014 extremely simple, no need to say more."}),(0,s.jsx)(t.p,{children:"Regarding individual stocks, since market sentiment is scattered, those that can buck the trend recently are mostly small-cap low-priced stocks. As year-end approaches, the restructuring farce is due for another performance \u2014 this is worth paying close attention to. As for the China-prefix stocks, they'll definitely remain the market's center of gravity, but you absolutely must nail the rhythm before doing short-term trades, or you'll be slaughtered."}),(0,s.jsx)(t.p,{children:"Don't feel like talking anymore. Every weekend, stocks become the most boring thing. Weekend \u2014 go indulge, develop the nightlife economy, contribute to the food-drink-fun economy. Whatever you do, don't do stocks. If you don't feel like doing anything, just meditate."}),(0,s.jsx)(t.p,{children:"Signing off first, see you later."})]})]})}function r(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(i,{...e})}):i(e)}},70507(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>m,frontMatter:()=>r,contentTitle:()=>h,toc:()=>c,assets:()=>l});var s=JSON.parse('{"id":"timeline/economics/ma5ambush","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/timeline/economics/ma5ambush.md","sourceDirName":"timeline/economics","slug":"/timeline/economics/ma5ambush","permalink":"/en/timeline/economics/ma5ambush","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"ma5ambush","title":"","hide_table_of_contents":true,"sidebar_label":"The 5-month moving average ambush script plays out as expected (2007/11/9 15:20:08)"},"sidebar":"timelineSidebar","previous":{"title":"The expected decisive battle\u2014bulls crumble at the first blow (2007/11/8 22:21:05)","permalink":"/en/timeline/economics/longbuyerscrash"},"next":{"title":"Teaching You Meditation 16: Consciousness and the Four Great Elements (2007/11/10 11:44:12)","permalink":"/en/timeline/zen/zazen16"}}'),o=n(74848),a=n(28453),i=n(71853);let r={id:"ma5ambush",title:"",hide_table_of_contents:!0,sidebar_label:"The 5-month moving average ambush script plays out as expected (2007/11/9 15:20:08)"},h,l={},c=[...i.RM];function d(e){return(0,o.jsx)(i.Ay,{})}function m(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var s=n(96540);let o={},a=s.createContext(o);function i(e){let t=s.useContext(a);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),s.createElement(a.Provider,{value:t},e.children)}}}]);